/* Progressive community upgrade. Legacy community remains intact until v2 RPC is available. */
(()=>{'use strict';
const cloud=window.ChiLeMeCloud,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const topics=['厨房日常','一人食','冰箱清空','新手求助','拿手好菜','翻车复盘'];
let lastAuth=cloud?.user?.id,active=false,tab='discover',topic='',sort='new',rows=[],epoch=0,busy=false,currentPerson=null,currentPost=null,chatPeer=null,chatId=null,chatMessages=[],editPost=null,files=[],previewURLs=[],inbox=[],polling=false;
const stamp=x=>new Date(x).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
const read=(a,p={})=>cloud.socialRead(a,p),write=(a,p={})=>cloud.socialWrite(a,p);
const avatar=(path,name)=>path?`<img class="sv-avatar" src="${esc(cloud.image(path))}" alt="${esc(name)}的头像" loading="lazy" decoding="async">`:`<span class="sv-avatar" aria-hidden="true">${esc((name||'饭').slice(0,1))}</span>`;
const person=(p)=>`<button class="sv-person" data-person="${esc(p.author_id||p.id||p.peer)}" aria-label="查看${esc(p.username)}的主页">${avatar(p.avatar_path,p.username)}<span>${esc(p.username)}</span></button>`;
function status(text,root='#sv-status'){const el=$(root);if(el)el.textContent=text||'';}
function login(){if(cloud.user)return true;document.querySelectorAll('.sv-dialog[open]').forEach(d=>d.close());location.hash='account';const d=$('.app-account-details');if(d)d.open=true;status('请先用自己的邮箱注册或登录。','#auth-status');return false;}
async function run(button,fn,target='#sv-status'){if(button?.disabled)return;const uid=cloud.user?.id;button&&(button.disabled=true);try{status('',target);await fn();}catch(e){status(e.message||'暂时无法完成，请稍后重试。',target);}finally{if(button?.isConnected)button.disabled=false;if(uid!==cloud.user?.id)clearPrivate();}}
function modal(id,title,body){let d=$('#'+id);if(!d){d=document.createElement('dialog');d.id=id;d.className='sv-dialog';d.setAttribute('aria-labelledby',id+'-heading');document.body.append(d);}d.innerHTML=`<div class="sv-dialog-head"><h2 id="${id}-heading">${esc(title)}</h2><button class="sv-close" type="button" aria-label="关闭${esc(title)}">×</button></div>${body}`;d.querySelector('.sv-close').onclick=()=>d.close();if(!d.open)d.showModal();return d;}
function wireImages(root){root.querySelectorAll('img:not(.sv-avatar)').forEach(img=>{img.onerror=()=>{const src=img.src,box=document.createElement('span');box.className='sv-image-fail';box.innerHTML='照片加载较慢或暂时失败<br><button type="button" class="sv-chip">重新加载</button>';img.replaceWith(box);box.querySelector('button').onclick=e=>{e.stopPropagation();box.replaceWith(img);img.src=src;};};});}
function pictures(p){return p.image_paths?.length?p.image_paths:p.image_path?[p.image_path]:[];}
function card(p){const images=pictures(p),thumb=p.thumb_paths?.[0]||images[0];return `<article class="sv-card">${thumb?`<button class="sv-photo" data-post="${esc(p.id)}" aria-label="查看${esc(p.title)}"><img src="${esc(cloud.image(thumb))}" alt="${esc(p.title)}" loading="lazy" decoding="async" width="480" height="540">${images.length>1?`<small>${images.length} 图</small>`:''}</button>`:''}<div class="sv-card-copy"><div class="sv-tag"># ${esc(p.topic||'厨房日常')}</div><button class="sv-title" data-post="${esc(p.id)}">${esc(p.title)}</button>${tab==='following'||!thumb?`<p class="sv-card-body">${esc(p.body)}</p>`:''}<div class="sv-card-bottom">${person(p)}<button class="sv-heart" data-heart="${esc(p.id)}" aria-label="${p.liked?'取消点赞':'点赞'}${esc(p.title)}" aria-pressed="${!!p.liked}" ${p.author_id===cloud.user?.id?'disabled':''}>${p.liked?'♥':'♡'} ${Number(p.like_count)||0}</button></div></div></article>`;}
function bindCards(root,list){root.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>showPerson(b.dataset.person));root.querySelectorAll('[data-post]').forEach(b=>b.onclick=()=>showPost(list.find(p=>p.id===b.dataset.post)));root.querySelectorAll('[data-heart]').forEach(b=>b.onclick=()=>{if(!login())return;run(b,async()=>{const p=list.find(x=>x.id===b.dataset.heart),liked=await write('like',{post:p.id});p.like_count=Number(p.like_count)+(liked?1:-1);p.liked=liked;b.textContent=(liked?'♥':'♡')+' '+p.like_count;b.setAttribute('aria-pressed',String(liked));});});wireImages(root);}
async function load(append=false){if(!active)return;const ticket=++epoch,uid=cloud.user?.id;status('正在端上饭友们的新动态…');try{const next=await read('feed',{tab,topic,sort,offset:append?rows.length:0});if(ticket!==epoch||uid!==cloud.user?.id)return;rows=append?[...rows,...next.filter(p=>!rows.some(x=>x.id===p.id))]:next;const root=$('#sv-feed');root.className='sv-feed'+(tab==='following'?' following':'');root.innerHTML=rows.length?rows.map(card).join(''):`<div class="sv-empty">${tab==='following'?'还没有关注动态。去发现页认识饭友，关注后会在这里看到他们。':tab==='saved'?'还没有收藏。打开喜欢的帖子，点击收藏。':topic?'这个话题还没有作品，来分享第一份吧。':'这里不放虚构帖子。来分享你的第一顿饭吧。'}</div>`;bindCards(root,rows);$('#sv-more').hidden=next.length<24;status('');}catch(e){if(ticket===epoch)status(e.message);}}
async function showPerson(id){const ticket=cloud.user?.id;try{const p=await read('profile',{peer:id});if(ticket!==cloud.user?.id)return;if(!p)throw Error('这个用户暂时不可用。');currentPerson=p;const own=p.id===cloud.user?.id;const f=p.friend;const d=modal('sv-profile','饭友主页',`<section class="sv-profile-head">${avatar(p.avatar_path,p.username)}<h3>${esc(p.username)}</h3><p class="sv-muted">${esc(p.bio||'好好做饭，慢慢认识。')}</p><div class="sv-stats"><div><strong>${p.post_count}</strong><small>作品</small></div><div><strong>${p.followers}</strong><small>关注者</small></div><div><strong>${p.following}</strong><small>关注</small></div></div><div class="sv-person-actions">${own?'<button id="sv-edit-profile">编辑我的资料</button>':`<button id="sv-follow" ${p.unavailable?'disabled':''}>${p.followed?'已关注 · 取消':'＋ 关注'}</button><button id="sv-friend" ${p.unavailable||f?.status==='declined'||f?.status==='pending'?'disabled':''}>${f?.status==='accepted'?'已是好友 · 移除':f?.status==='pending'?'好友申请待处理':f?.status==='declined'?'申请未通过':'添加好友'}</button><button id="sv-dm" ${p.unavailable?'disabled':''}>私信</button><button id="sv-block">${p.blocked?'解除拉黑':'拉黑'}</button><button id="sv-report-person">举报</button>`}</div>${f?.status==='pending'&&f.sender!==cloud.user?.id?'<button class="sv-chip" id="sv-person-accept">接受好友申请</button>':''}</section><p id="sv-person-status" class="sv-status" role="status"></p><div id="sv-person-feed" class="sv-feed"></div><button id="sv-person-more" class="sv-chip sv-more" hidden>更多作品</button>`);
 if(own)$('#sv-edit-profile').onclick=()=>{d.close();location.hash='account';$('.app-account-details').open=true;};else{
 $('#sv-follow').onclick=e=>{if(login())run(e.target,async()=>{await write('follow',{peer:id,enabled:!p.followed});await showPerson(id);},'#sv-person-status');};
 $('#sv-friend').onclick=e=>{if(!login())return;if(f?.status==='accepted'){confirmAction('移除好友','移除后仍保留聊天记录。',async()=>{await write('unfriend',{peer:id});await showPerson(id);});}else run(e.target,async()=>{await write('friend_request',{peer:id});await showPerson(id);},'#sv-person-status');};
 $('#sv-dm').onclick=()=>openChat(id,p.username);
 $('#sv-block').onclick=()=>{if(login())confirmAction(p.blocked?'解除拉黑':'拉黑这位饭友',p.blocked?'解除后不会自动恢复关注、好友或聊天权限。':'双方将不能继续发私信或添加好友；对方的帖子不再出现在你的社区。',async()=>{await write('block',{peer:id,enabled:!p.blocked});await showPerson(id);load();});};
 $('#sv-report-person').onclick=()=>report({peer:id});
 }
 const accept=$('#sv-person-accept');if(accept)accept.onclick=e=>run(e.target,async()=>{await write('friend_reply',{peer:id,decision:'accepted'});await showPerson(id);},'#sv-person-status');
 let posts=[];async function more(){const next=await read('feed',{peer:id,offset:posts.length});if(currentPerson?.id!==id||!d.open)return;posts.push(...next);const r=$('#sv-person-feed');r.innerHTML=posts.length?posts.map(card).join(''):'<p class="sv-empty">暂无可见作品</p>';bindCards(r,posts);$('#sv-person-more').hidden=next.length<24;}$('#sv-person-more').onclick=e=>run(e.target,more,'#sv-person-status');await more();
 }catch(e){status(e.message);}}
function confirmAction(title,text,fn){const d=modal('sv-confirm',title,`<p>${esc(text)}</p><button class="sv-compose" id="sv-confirm-yes">确认</button><p class="sv-status" id="sv-confirm-status" role="status"></p>`);$('#sv-confirm-yes').onclick=e=>run(e.target,async()=>{await fn();d.close();},'#sv-confirm-status');}
function report(args){if(!login())return;const d=modal('sv-report','举报内容',`<p class="sv-muted">提交给项目管理员审核。紧急骚扰可先拉黑；举报不会自动删除帖子。</p><form id="sv-report-form"><label>举报原因<textarea required minlength="2" maxlength="500" rows="4"></textarea></label><button class="sv-compose">提交举报</button></form><p id="sv-report-status" class="sv-status" role="status"></p>`);$('#sv-report-form').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{await write('report',{...args,reason:e.target.querySelector('textarea').value});e.target.hidden=true;status('已提交，等待管理员处理。','#sv-report-status');},'#sv-report-status');};}
async function showPost(p){if(!p)return;currentPost=p;const own=p.author_id===cloud.user?.id;const d=modal('sv-post',p.title,`${person(p)}<p class="sv-muted">${stamp(p.created_at)} · #${esc(p.topic||'厨房日常')}</p><div class="sv-gallery">${pictures(p).map((path,i)=>`<img src="${esc(cloud.image(path))}" alt="${esc(p.title)} 第${i+1}张照片" loading="${i?'lazy':'eager'}" decoding="async">`).join('')}</div>${pictures(p).length>1?'<p class="sv-muted">左右滑动查看全部照片</p>':''}<p class="sv-body">${esc(p.body)}</p>${p.recipe_id?'<button class="sv-chip" id="sv-recipe">查看关联菜谱</button>':''}<div class="sv-actions"><button id="sv-save">${p.saved?'已收藏 · 取消':'收藏'}</button>${own?'<button id="sv-edit">编辑</button><button id="sv-withdraw">撤下帖子</button>':'<button id="sv-report-post">举报</button>'}</div><h3>聊聊这一顿</h3><div id="sv-comments"></div><form id="sv-comment"><label>留言<textarea required maxlength="500" rows="2" placeholder="聊聊口味，问问做法…"></textarea></label><button class="sv-compose">发送评论</button></form><p id="sv-post-status" class="sv-status" role="status"></p>`);d.querySelector('[data-person]').onclick=()=>showPerson(p.author_id);wireImages(d);
 if(p.recipe_id)$('#sv-recipe').onclick=()=>{d.close();window.ChiLeMe.openRecipe(p.recipe_id);};
 $('#sv-save').onclick=e=>{if(login())run(e.target,async()=>{p.saved=await write('save',{post:p.id,enabled:!p.saved});e.target.textContent=p.saved?'已收藏 · 取消':'收藏';},'#sv-post-status');};
 if(own){$('#sv-edit').onclick=()=>compose(p);$('#sv-withdraw').onclick=()=>confirmAction('撤下这篇帖子','撤下后将不再公开展示，原始记录仍保存在服务器。',async()=>{await write('withdraw',{post:p.id});d.close();await load();});}else $('#sv-report-post').onclick=()=>report({post:p.id});
 async function comments(){const uid=cloud.user?.id,list=await read('comments',{post:p.id});if(currentPost?.id!==p.id||uid!==cloud.user?.id)return;const root=$('#sv-comments');root.innerHTML=list.length?list.map(c=>`<div class="sv-row"><div>${person(c)}<p>${esc(c.body)}</p><small class="sv-muted">${stamp(c.created_at)}</small></div></div>`).join(''):'<p class="sv-muted">还没有评论，来聊聊吧。</p>';root.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>showPerson(b.dataset.person));}
 $('#sv-comment').onsubmit=e=>{e.preventDefault();if(login())run(e.submitter,async()=>{await write('comment',{post:p.id,body:e.target.querySelector('textarea').value});e.target.reset();await comments();},'#sv-post-status');};try{await comments();}catch(e){status(e.message,'#sv-post-status');}}
async function compress(file,maxSide,quality){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20*1024*1024)throw Error('请选择 JPG、PNG 或 WebP 图片，每张不超过 20 MB。');const url=URL.createObjectURL(file);try{const img=await new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('图片无法读取，请重新选择或转为 JPG。'));i.src=url;});if(img.naturalWidth*img.naturalHeight>50000000)throw Error('图片尺寸过大，请选择普通照片。');const scale=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',quality));canvas.width=canvas.height=1;if(!blob||blob.size>5*1024*1024)throw Error('压缩失败，请选择较小的照片。');return blob;}finally{URL.revokeObjectURL(url);}}
function releasePreviews(){previewURLs.forEach(u=>URL.revokeObjectURL(u));previewURLs=[];}
function compose(p=null){if(!login())return;editPost=p;files=[];releasePreviews();const d=modal('sv-compose','分享厨房日常',`<p class="sv-muted">向所有饭友公开。可只写文字，或添加最多 9 张照片；照片会压缩并生成缩略图。</p><form id="sv-publish"><label>标题<input id="sv-title" required minlength="2" maxlength="60" placeholder="这一顿，有什么想分享？" value="${esc(p?.title||'')}"></label><label>内容<textarea id="sv-body" required maxlength="1500" rows="5" placeholder="今天做了什么，遇到了什么问题…">${esc(p?.body||'')}</textarea></label><label>话题<select id="sv-topic">${topics.map(t=>`<option ${p?.topic===t?'selected':''}>${t}</option>`).join('')}</select></label><label>关联菜谱（可选）<select id="sv-recipe-choice"><option value="">不关联菜谱</option>${window.recipeBook.map(r=>`<option value="${esc(r.id)}" ${r.id===p?.recipe_id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label><label>选择照片（重新选择会替换这一组）<input id="sv-files" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><div id="sv-previews" class="sv-previews">${p?pictures(p).map(x=>`<img src="${esc(cloud.image(x))}" alt="已有照片">`).join(''):''}</div><button class="sv-chip" id="sv-clear-images" type="button">移除全部照片</button><p class="sv-muted">请勿上传他人隐私或未获许可的照片。发布前请检查内容。</p><button class="sv-compose" type="submit">${p?'保存修改':'发布给饭友'}</button></form><p id="sv-publish-status" class="sv-status" role="status"></p>`);let keep=p?pictures(p):[],keepThumbs=p?(p.thumb_paths?.length?p.thumb_paths:pictures(p)):[];
 $('#sv-files').onchange=e=>{const next=Array.from(e.target.files);if(next.length>9){e.target.value='';status('最多选择 9 张照片。','#sv-publish-status');return;}if(next.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>20*1024*1024)){e.target.value='';status('请选择 JPG、PNG、WebP，每张不超过 20 MB。','#sv-publish-status');return;}files=next;keep=[];keepThumbs=[];releasePreviews();previewURLs=files.map(f=>URL.createObjectURL(f));$('#sv-previews').innerHTML=previewURLs.map(u=>`<img src="${u}" alt="待发布的照片预览">`).join('');status('','#sv-publish-status');};
 $('#sv-clear-images').onclick=()=>{files=[];keep=[];keepThumbs=[];releasePreviews();$('#sv-files').value='';$('#sv-previews').innerHTML='';};d.onclose=releasePreviews;
 $('#sv-publish').onsubmit=e=>{e.preventDefault();if(busy)return;run(e.submitter,async()=>{busy=true;const uid=cloud.user?.id;const data={post:p?.id,title:$('#sv-title').value,body:$('#sv-body').value,topic:$('#sv-topic').value,recipe:$('#sv-recipe-choice').value,images:[...keep],thumbs:[...keepThumbs]};const selected=[...files];const controls=Array.from(e.target.elements);controls.forEach(x=>x.disabled=true);d.querySelector('.sv-close').disabled=true;d.oncancel=ev=>ev.preventDefault();try{for(let i=0;i<selected.length;i++){status(`正在处理照片 ${i+1}/${selected.length}…`,'#sv-publish-status');const large=await compress(selected[i],1600,.8),small=await compress(selected[i],480,.72);if(uid!==cloud.user?.id)throw Error('账号已变化，请重新发布。');data.images.push(await cloud.upload(large,'dish'));data.thumbs.push(await cloud.upload(small,'dish'));}if(uid!==cloud.user?.id)throw Error('账号已变化，请重新发布。');await write(p?'edit':'publish',data);d.close();$('#sv-post')?.close();await load();status('已保存到云端，其他饭友现在可以看到。');}finally{busy=false;controls.forEach(x=>x.disabled=false);d.querySelector('.sv-close').disabled=false;d.oncancel=null;}},'#sv-publish-status');};}
async function showFriends(){if(!login())return;const uid=cloud.user.id,list=await read('friends');if(uid!==cloud.user?.id)return;const d=modal('sv-friends','好友与申请',`<p class="sv-muted">好友需要双方同意；关注则用于订阅动态。</p><div id="sv-friend-list">${list.length?list.map(p=>`<div class="sv-row"><div>${person({...p,id:p.peer})}<p>${p.status==='accepted'?'已是好友':p.recipient===uid?'请求成为你的好友':'等待对方同意'}</p></div>${p.status==='pending'&&p.recipient===uid?`<button class="sv-chip" data-reply="accepted" data-peer="${p.peer}">接受</button><button class="sv-chip" data-reply="declined" data-peer="${p.peer}">拒绝</button>`:''}</div>`).join(''):'<p class="sv-empty">还没有好友申请。点击饭友头像，去认识他们。</p>'}</div><button id="sv-block-list" class="sv-chip">管理黑名单</button><p class="sv-status" id="sv-friend-status" role="status"></p>`);d.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>showPerson(b.dataset.person));d.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>run(b,async()=>{await write('friend_reply',{peer:b.dataset.peer,decision:b.dataset.reply});await showFriends();},'#sv-friend-status'));$('#sv-block-list').onclick=()=>run(null,showBlocks,'#sv-friend-status');}
async function showBlocks(){const list=await read('blocks');const d=modal('sv-blocks','黑名单',list.length?list.map(p=>`<div class="sv-row"><div>${esc(p.username)}</div><button class="sv-chip" data-unblock="${p.id}">解除拉黑</button></div>`).join(''):'<p class="sv-empty">黑名单为空。</p>');d.querySelectorAll('[data-unblock]').forEach(b=>b.onclick=()=>confirmAction('解除拉黑','解除后不会自动恢复好友或聊天权限。',async()=>{await write('block',{peer:b.dataset.unblock,enabled:false});await showBlocks();}));}
async function refreshInbox(){if(!active||!cloud.user)return;const uid=cloud.user.id,list=await read('inbox');if(uid!==cloud.user?.id)return;inbox=list;const unread=list.reduce((n,x)=>n+Number(x.unread),0);$('#sv-inbox-button').textContent=unread?`消息 (${unread>99?'99+':unread})`:'消息';return list;}
async function showInbox(){if(!login())return;await refreshInbox();const uid=cloud.user.id;const d=modal('sv-inbox','消息',`<p class="sv-muted">陌生人只能发一条申请；接受后才能继续聊天。当前仅文字私信，页面打开时定时更新。</p>${inbox.length?inbox.map(t=>`<div class="sv-row"><div>${person({...t,id:t.peer})}<p>${esc(t.last_body||'暂无消息')}</p><small class="sv-muted">${t.status==='pending'?(t.recipient===uid?'新消息申请':'等待对方接受'):t.status==='declined'?'会话已关闭':stamp(t.last_at)}</small></div><button class="sv-chip" data-chat="${t.id}">${Number(t.unread)?`未读 ${t.unread}`:'查看'}</button></div>`).join(''):'<p class="sv-empty">还没有私信。打开饭友主页，向对方打个招呼吧。</p>'}<p id="sv-inbox-status" class="sv-status" role="status"></p>`);d.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>showPerson(b.dataset.person));d.querySelectorAll('[data-chat]').forEach(b=>b.onclick=()=>{const t=inbox.find(x=>x.id===b.dataset.chat);openChat(t.peer,t.username,t.id);});}
async function openChat(peer,name,id=null){if(!login())return;chatPeer=peer;chatId=id;chatMessages=[];const d=modal('sv-chat','与 '+name+' 聊聊',`<p class="sv-muted">请勿分享密码、验证码、住址或付款信息。</p><div id="sv-chat-state"></div><button class="sv-chip" id="sv-chat-older" hidden>查看更早消息</button><div class="sv-chat-log" id="sv-chat-log" aria-live="polite"></div><form id="sv-send" class="sv-message-form"><label>消息<textarea required maxlength="1000" rows="2" placeholder="聊聊做饭吧…"></textarea></label><button class="sv-compose">发送</button></form><p id="sv-chat-status" class="sv-status" role="status"></p><div class="sv-actions"><button class="sv-chip" id="sv-chat-person">查看主页 / 拉黑举报</button><button class="sv-chip" id="sv-chat-refresh">刷新消息</button></div>`);$('#sv-chat-person').onclick=()=>showPerson(peer);$('#sv-chat-refresh').onclick=e=>run(e.target,()=>readChat(false),'#sv-chat-status');$('#sv-chat-older').onclick=e=>run(e.target,()=>readChat(true),'#sv-chat-status');
 $('#sv-send').onsubmit=e=>{e.preventDefault();run(e.submitter,async()=>{const result=await write('send',{peer,body:e.target.querySelector('textarea').value});chatId=result.thread;e.target.reset();await readChat();await refreshInbox();},'#sv-chat-status');};
 try{if(!chatId){await refreshInbox();chatId=inbox.find(t=>t.peer===peer)?.id||null;}if(chatId)await readChat();else $('#sv-chat-state').innerHTML='<p class="sv-warning">如果你们还不是好友，只能发送一条消息申请。对方接受后才能继续聊。</p>';}catch(e){status(e.message,'#sv-chat-status');}}
async function readChat(older=false){if(!chatId||!$('#sv-chat')?.open)return;const id=chatId,uid=cloud.user?.id;const data=await read('messages',{thread:id,...(older?{before:chatMessages[0]?.id}:{} )});if(id!==chatId||uid!==cloud.user?.id||!$('#sv-chat')?.open)return;const t=data.thread;const firstLoad=chatMessages.length===0;chatMessages=[...new Map([...chatMessages,...data.messages].map(m=>[m.id,m])).values()].sort((a,b)=>a.id-b.id);if(older||firstLoad)$('#sv-chat-older').hidden=data.messages.length<50;const log=$('#sv-chat-log'),nearBottom=log.scrollHeight-log.scrollTop-log.clientHeight<70;log.innerHTML=chatMessages.map(m=>`<div class="sv-bubble ${m.sender===uid?'mine':''}">${esc(m.body)}<time>${stamp(m.created_at)}</time></div>`).join('')||'<p class="sv-muted">暂无消息。</p>';if(!older&&nearBottom)log.scrollTop=log.scrollHeight;const pending=t.status==='pending',incoming=pending&&t.recipient===uid;$('#sv-chat-state').innerHTML=pending?`<p class="sv-warning">${incoming?'这是一条陌生人消息申请。是否接受？':'已发送申请，等待对方接受后才能继续发送。'}</p>${incoming?'<div class="sv-actions"><button data-chat-reply="accepted">接受聊天</button><button data-chat-reply="declined">拒绝</button></div>':''}`:t.status==='declined'?'<p class="sv-warning">会话已关闭，不能继续发送。</p>':'';$('#sv-send').hidden=t.status!=='accepted';$('#sv-chat-state').querySelectorAll('[data-chat-reply]').forEach(b=>b.onclick=()=>run(b,async()=>{await write('chat_reply',{thread:id,decision:b.dataset.chatReply});await readChat();},'#sv-chat-status'));if(!older&&data.messages.length)await write('read',{thread:id,last:data.messages.at(-1).id});}
function clearPrivate(){epoch++;chatPeer=null;chatId=null;chatMessages=[];inbox=[];currentPerson=null;currentPost=null;document.querySelectorAll('.sv-dialog').forEach(d=>{d.close();d.innerHTML='';});releasePreviews();if($('#sv-inbox-button'))$('#sv-inbox-button').textContent='消息';}
function mount(){if(active)return;const section=$('#community');const root=document.createElement('div');root.id='social-v2';root.innerHTML=`<div class="sv-top"><div><span class="sv-kicker">一起做饭 · 一起好好吃</span><h1>饭友的厨房日常</h1><p>晒一顿饭，认识一个同样认真生活的人。</p></div><button class="sv-compose" id="sv-new">＋ 发布</button></div><div class="sv-tools"><button id="sv-inbox-button">消息</button><button id="sv-friends-button">好友与申请</button><button id="sv-mine">我的主页</button><button id="sv-refresh">↻ 刷新</button></div><div class="sv-tabs" role="tablist" aria-label="社区内容"><button role="tab" data-sv-tab="discover" aria-selected="true">发现</button><button role="tab" data-sv-tab="following" aria-selected="false">关注</button><button role="tab" data-sv-tab="saved" aria-selected="false">收藏</button></div><div class="sv-topics"><button class="sv-chip" data-topic="" aria-pressed="true">全部</button>${topics.map(t=>`<button class="sv-chip" data-topic="${t}" aria-pressed="false"># ${t}</button>`).join('')}<button class="sv-chip" id="sv-sort" aria-pressed="false">热门优先</button></div><p id="sv-status" class="sv-status" role="status"></p><div id="sv-feed" class="sv-feed"></div><button id="sv-more" class="sv-chip sv-more" hidden>加载更多</button>`;
 Array.from(section.children).forEach(el=>el.hidden=true);section.append(root);section.classList.add('community-v2');active=true;window.ChiLeMeSocialV2={active:true};
 $('#sv-new').onclick=()=>compose();$('#sv-inbox-button').onclick=e=>run(e.target,showInbox);$('#sv-friends-button').onclick=e=>run(e.target,showFriends);$('#sv-mine').onclick=()=>{if(login())showPerson(cloud.user.id);};$('#sv-refresh').onclick=()=>load();$('#sv-more').onclick=()=>load(true);
 root.querySelectorAll('[data-sv-tab]').forEach(b=>b.onclick=()=>{if(b.dataset.svTab!=='discover'&&!login())return;tab=b.dataset.svTab;root.querySelectorAll('[data-sv-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));load();});root.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{topic=b.dataset.topic;root.querySelectorAll('[data-topic]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));load();});$('#sv-sort').onclick=e=>{sort=sort==='new'?'likes':'new';e.target.setAttribute('aria-pressed',String(sort==='likes'));load();};
 const links=$('.app-personal-links');if(links){const b=document.createElement('button');b.type='button';b.innerHTML='<span>我的饭友主页<small>公开作品、关注和好友</small></span><b>›</b>';b.onclick=()=>{if(login())showPerson(cloud.user.id);};links.append(b);}
 load();}
async function check(){if(active||!cloud?.ready)return;try{const v=await read('version');if(v?.version===2)mount();}catch{/* Deliberate fallback: old community remains usable, no migration presumed. */}}
window.addEventListener('chileme:auth',()=>{if(lastAuth===cloud.user?.id)return;lastAuth=cloud.user?.id;clearPrivate();if(active){tab='discover';$('#social-v2').querySelectorAll('[data-sv-tab]').forEach(x=>x.setAttribute('aria-selected',String(x.dataset.svTab===tab)));load();}});
window.addEventListener('hashchange',()=>{if(location.hash==='#community'){active?load():check();}else document.querySelectorAll('.sv-dialog[open]').forEach(d=>d.close());});
setInterval(async()=>{if(polling||document.hidden||!active||!cloud.user||location.hash!=='#community')return;polling=true;try{await refreshInbox();if($('#sv-chat')?.open)await readChat();}catch{/* Manual refresh exposes errors without interrupting reading. */}finally{polling=false;}},30000);
check();
})();
